const {chromium}=require('@playwright/test');const fs=require('fs');const dns=require('dns').promises;const hosts=['syntropix.in','www.syntropix.in','github.com','example.com'];const widths=[320,390,768,1024,1440];const routes=['/','/professionals.html','/employee-experience.html','/pricing.html','/solutions.html','/enterprise.html'];(async()=>{const report={dns:{},pages:[],errors:[]};for(const h of hosts){try{report.dns[h]=await dns.lookup(h,{all:true});}catch(e){report.dns[h]={error:e.message};}}const browser=await chromium.launch();fs.mkdirSync('production-evidence',{recursive:true});for(const route of routes){for(const width of widths){const page=await browser.newPage({viewport:{width,height:900},reducedMotion:'reduce'});try{const response=await page.goto('https://www.syntropix.in'+route,{waitUntil:'load',timeout:30000});await page.evaluate(()=>document.fonts.ready);await page.waitForTimeout(300);const m=await page.evaluate(()=>{const grid=document.querySelector('.assessment-catalogue-inline .assessment-grid');const savings=document.querySelector('.assessment-catalogue-inline .assessment-savings');const label=savings?.closest('.assessment-saving-line')?.querySelector(':scope > span');const ls=[...(savings?.children||[])];return {title:document.title,overflow:document.documentElement.scrollWidth-document.documentElement.clientWidth,columns:grid?getComputedStyle(grid).gridTemplateColumns.split(' ').filter(Boolean).length:null,savingsLabel:label?.textContent.trim(),savingsRows:ls.map(e=>e.textContent.trim()),discountRowsSeparate:ls.length===2?Math.abs(ls[0].getBoundingClientRect().top-ls[1].getBoundingClientRect().top)>3:null};});report.pages.push({route,width,status:response.status(),url:page.url(),...m});await page.screenshot({path:'production-evidence/'+(route.replace(/[^a-z0-9]/gi,'_')||'home')+'-'+width+'.png',fullPage:true,animations:'disabled'});}catch(e){report.errors.push({route,width,error:e.message});}finally{await page.close();}}}await browser.close();fs.writeFileSync('production-evidence/report.json',JSON.stringify(report,null,2));console.log(JSON.stringify(report));if(report.errors.length||report.pages.some(p=>p.status>=400||p.overflow>2||p.route==='/professionals.html'&&(p.columns!==(p.width>=1200?3:p.width>=768?2:1)||p.savingsRows.length!==2||!p.discountRowsSeparate)))process.exitCode=1})().catch(e=>{console.error(e);process.exitCode=1});